  projects: [
    { id:"c11_proj_1", title:"Self-Balancing Robot", subject:"Electrical & Control Systems", difficulty:"Advanced", estimatedTime:"6-8 hours", estimatedCost:"₹2,000-3,000",
      description:"Build a two-wheeled self-balancing robot using MPU6050 IMU, Arduino, and PID control.",
      components:["Arduino Uno/Nano","MPU6050 IMU (6-axis)","2x NEMA 17 Stepper Motors","2x A4988 Stepper Drivers","12V Power Supply","Robot Chassis","Jumper Wires","Breadboard"],
      steps:["Design and build a compact chassis with two wheels","Mount stepper motors as the two wheels","Attach MPU6050 IMU at the center of mass","Wire A4988 stepper drivers to Arduino","Wire MPU6050 via I2C","Upload self-balancing code","Tune PID parameters (start with Kp)","Test on flat surface","Gradually increase Kd and Ki","Fine-tune for stability"],
      arduinoCode:`#include <Wire.h>
#include <MPU6050.h>

MPU6050 mpu;
const int stepPin = 3, dirPin = 4;
float Kp = 15, Ki = 0.01, Kd = 0.5;
float error, integral, derivative, lastError;
float setpoint = 0;
float currentAngle;

void setup() {
  Wire.begin();
  mpu.initialize();
  pinMode(stepPin, OUTPUT);
  pinMode(dirPin, OUTPUT);
  Serial.begin(115200);
}

void loop() {
  int16_t ax, ay, az, gx, gy, gz;
  mpu.getMotion6(&ax, &ay, &az, &gx, &gy, &gz);
  
  // Calculate angle from accelerometer
  float accelAngle = atan2(ay, az) * 180 / PI;
  
  // Complementary filter for stable angle
  currentAngle = 0.98 * (currentAngle + gx * 0.01) + 0.02 * accelAngle;
  
  // PID control
  error = setpoint - currentAngle;
  integral += error;
  derivative = error - lastError;
  float output = Kp * error + Ki * integral + Kd * derivative;
  lastError = error;
  
  // Drive motors
  if (output > 0) digitalWrite(dirPin, HIGH);
  else digitalWrite(dirPin, LOW);
  
  int speed = constrain(abs(output), 0, 255);
  analogWrite(stepPin, speed);
  
  Serial.print("Angle: "); Serial.print(currentAngle);
  Serial.print(" Output: "); Serial.println(output);
  delay(10);
}`,
      troubleshooting:["Robot falls immediately → Check IMU orientation and mounting","Oscillates wildly → Reduce Kp, increase Kd","Drifts in one direction → Adjust setpoint offset","Motors stuttering → Check power supply adequacy"],
      testingChecklist:["IMU reads angle correctly","Motors respond to angle changes","Robot balances for 5+ seconds","PID responds to disturbances","No motor stuttering at speed"] },
    { id:"c11_proj_2", title:"WiFi Robot Arm (ESP32)", subject:"Microcontrollers", difficulty:"Advanced", estimatedTime:"5-6 hours", estimatedCost:"₹2,200-3,200",
      description:"Build a 4-DOF robot arm controlled via WiFi web interface using ESP32 and servo motors.",
      components:["ESP32 Dev Board","4x SG90 Servo Motors","Robot Arm Kit (acrylic)","External 5V Power Supply","Breadboard","Jumper Wires"],
      steps:["Assemble robot arm kit with 4 servos","Wire servos to ESP32 (GPIO 13,12,14,27)","Power servos from external 5V supply (common ground)","Upload WiFi web server code","Connect ESP32 to WiFi","Access web interface from browser","Test individual joint control","Create preset positions (home, grab, release)","Add smooth motion between positions","Test full pick-and-place sequence"],
      arduinoCode:`#include <WiFi.h>
#include <WebServer.h>
#include <ESP32Servo.h>

const char* ssid = "YOUR_WIFI";
const char* password = "YOUR_PASSWORD";
WebServer server(80);

Servo base, shoulder, elbow, gripper;
const int basePin = 13, shoulderPin = 12, elbowPin = 14, gripperPin = 27;

void moveTo(int b, int s, int e, int g) {
  base.write(b); shoulder.write(s); elbow.write(e); gripper.write(g);
  delay(500);
}

void handleRoot() {
  String html = "<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>";
  html += "<style>body{font-family:Arial;background:#0a0f1e;color:#00d2ff;text-align:center;padding:20px}";
  html += "button{background:rgba(0,210,255,0.2);color:#00d2ff;border:1px solid #00d2ff;border-radius:10px;padding:15px 30px;margin:5px;font-size:16px}</style>";
  html += "</head><body><h1>Robot Arm Control</h1>";
  html += "<button onclick=fetch('/home')>Home</button><br>";
  html += "<button onclick=fetch('/grab')>Grab</button>";
  html += "<button onclick=fetch('/release')>Release</button>";
  html += "<script>function fetch(u){var x=new XMLHttpRequest();x.open('GET',u);x.send()}</script>";
  html += "</body></html>";
  server.send(200, "text/html", html);
}

void setup() {
  base.attach(basePin); shoulder.attach(shoulderPin);
  elbow.attach(elbowPin); gripper.attach(gripperPin);
  WiFi.begin(ssid, password);
  while (WiFi.status() != WL_CONNECTED) delay(500);
  server.on("/", handleRoot);
  server.on("/home", []() { moveTo(90,90,90,90); server.send(200,"text/plain","OK"); });
  server.on("/grab", []() { moveTo(90,60,120,40); server.send(200,"text/plain","OK"); });
  server.on("/release", []() { moveTo(90,60,120,120); server.send(200,"text/plain","OK"); });
  server.begin();
}

void loop() { server.handleClient(); }`,
      troubleshooting:["Servos jittering → Use external power supply, add capacitors","WiFi not connecting → Check credentials","Servos not moving → Verify pin assignments and PWM","Web page not loading → Check ESP32 IP address"],
      testingChecklist:["All 4 servos move individually","ESP32 connects to WiFi","Web interface loads","Home position works","Grab and release positions work","Smooth motion between positions"] }
  ],
